/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var hasBigIntSupport = require( '@stdlib/assert/has-bigint-support' );
var uniform = require( '@stdlib/random/base/uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var BigInt = require( '@stdlib/bigint/ctor' );
var Number = require( '@stdlib/number/ctor' );
var dgemm = require( '@stdlib/blas/base/dgemm' ).ndarray;
var frexp = require( '@stdlib/math/base/special/frexp' );
var ldexp = require( '@stdlib/math/base/special/ldexp' );
var pow = require( '@stdlib/math/base/special/pow' );
var abs = require( '@stdlib/math/base/special/abs' );
var min = require( '@stdlib/math/base/special/min' );
var defaults = require( './../lib/defaults.js' );
var winograd = require( './../lib/winograd.js' );
var depth = require( './../lib/depth.js' );


// VARIABLES //

var SEED = 20261103;
var NT = 'no-transpose';
var EPS = pow( 2.0, -53 ); // unit roundoff
var CUTOFF = 4;

// The exact reference products require `BigInt` support:
var opts = {
	'skip': !hasBigIntSupport()
};
var ZERO = ( opts.skip ) ? null : BigInt( 0 );

// Number of invocations of the Strassen–Winograd kernel by `base.js` (updated by a spy):
var ncalls = 0;

var base = proxyquire( './../lib/base.js', {
	'./winograd.js': spy
});

// Public ndarray interface (default cutoff and levels) whose kernel invocations are recorded by the spy:
var ndarray = proxyquire( './../lib/ndarray.js', {
	'./base.js': base
});


// FUNCTIONS //

/**
* Invokes the Strassen–Winograd kernel and records the invocation.
*
* @private
* @returns {Float64Array} output matrix
*/
function spy() {
	ncalls += 1;
	return winograd.apply( null, arguments );
}

/**
* Decomposes a finite double `x` into an odd integer `m` and an exponent `e` such that `x = m·2^e` (or `[0,0]` when `x` is zero).
*
* @private
* @param {number} x - finite double
* @returns {Array} integer significand and exponent
*/
function decompose( x ) {
	var f;
	var m;
	var e;

	if ( x === 0.0 ) {
		return [ 0.0, 0 ];
	}
	f = frexp( x ); // x = f[0]·2^f[1], where 0.5 <= |f[0]| < 1
	m = ldexp( f[ 0 ], 53 );
	e = f[ 1 ] - 53;
	while ( m%2 === 0 ) {
		m /= 2;
		e += 1;
	}
	return [ m, e ];
}

/**
* Returns the smallest scaling exponent `s` such that `x·2^s` is an integer for every element `x` of a matrix.
*
* @private
* @param {Float64Array} X - matrix
* @returns {integer} scaling exponent
*/
function scaleExponent( X ) {
	var e;
	var i;

	e = 0;
	for ( i = 0; i < X.length; i++ ) {
		if ( X[ i ] !== 0.0 ) {
			e = min( e, decompose( X[ i ] )[ 1 ] );
		}
	}
	return -e;
}

/**
* Returns `x·2^s` as an exact BigInt.
*
* @private
* @param {number} x - finite double such that `x·2^s` is an integer
* @param {integer} s - scaling exponent
* @returns {BigInt} scaled value
*/
function toBigInt( x, s ) {
	var d = decompose( x );
	return BigInt( d[ 0 ] ) << BigInt( d[ 1 ]+s );
}

/**
* Computes the exact product of two square row-major matrices, scaled by `2^(sa+sb)`.
*
* @private
* @param {PositiveInteger} n - order
* @param {Float64Array} A - first matrix (row-major)
* @param {Float64Array} B - second matrix (row-major)
* @param {integer} sa - scaling exponent for `A`
* @param {integer} sb - scaling exponent for `B`
* @returns {Array<BigInt>} exact product (row-major)
*/
function exactProduct( n, A, B, sa, sb ) {
	var out;
	var bt;
	var ai;
	var s;
	var i;
	var j;
	var k;

	ai = [];
	bt = [];
	for ( i = 0; i < n; i++ ) {
		for ( j = 0; j < n; j++ ) {
			ai.push( toBigInt( A[ (i*n)+j ], sa ) );
			bt.push( toBigInt( B[ (j*n)+i ], sb ) ); // transposed
		}
	}
	out = [];
	for ( i = 0; i < n; i++ ) {
		for ( j = 0; j < n; j++ ) {
			s = ZERO;
			for ( k = 0; k < n; k++ ) {
				s += ai[ (i*n)+k ] * bt[ (j*n)+k ];
			}
			out.push( s );
		}
	}
	return out;
}

/**
* Returns the maximum absolute error `max|C - Ĉ|` of a computed product, evaluated exactly (up to the final conversion to a double).
*
* @private
* @param {Float64Array} C - computed product (row-major)
* @param {Array<BigInt>} exact - exact product scaled by `2^s` (row-major)
* @param {integer} s - scaling exponent of the exact product
* @returns {number} maximum absolute error
*/
function maxError( C, exact, s ) {
	var diff;
	var err;
	var sh;
	var d;
	var i;

	err = 0.0;
	for ( i = 0; i < C.length; i++ ) {
		d = decompose( C[ i ] );
		sh = d[ 1 ] + s;
		if ( sh >= 0 ) {
			diff = ( BigInt( d[ 0 ] ) << BigInt( sh ) ) - exact[ i ];
			sh = s;
		} else {
			// The computed value lies on a finer grid than the exact product, so compare on the finer grid:
			diff = BigInt( d[ 0 ] ) - ( exact[ i ] << BigInt( -sh ) );
			sh = s - sh;
		}
		if ( diff < ZERO ) {
			diff = -diff;
		}
		err = max2( err, ldexp( Number( diff ), -sh ) );
	}
	return err;
}

/**
* Returns the maximum of two numbers.
*
* @private
* @param {number} x - first number
* @param {number} y - second number
* @returns {number} maximum
*/
function max2( x, y ) {
	return ( x > y ) ? x : y;
}

/**
* Returns the maximum absolute value of a matrix.
*
* @private
* @param {Float64Array} X - matrix
* @returns {number} maximum absolute value
*/
function maxAbs( X ) {
	var m;
	var i;

	m = 0.0;
	for ( i = 0; i < X.length; i++ ) {
		m = max2( m, abs( X[ i ] ) );
	}
	return m;
}

/**
* Returns the normwise error bound constant `f_W = 18^L·(k0² + 5.5625·k0) - 5.5625·K` of the Winograd variant, where `k0 = K/2^L`.
*
* @private
* @param {PositiveInteger} K - inner dimension
* @param {NonNegativeInteger} L - number of recursion levels
* @returns {number} bound constant
*/
function fW( K, L ) {
	var k0 = K / pow( 2.0, L );
	return ( pow( 18.0, L ) * ( ( k0*k0 ) + ( 5.5625*k0 ) ) ) - ( 5.5625*K );
}

/**
* Returns a copy of a square row-major matrix stored in column-major order.
*
* @private
* @param {PositiveInteger} n - order
* @param {Float64Array} X - matrix (row-major)
* @returns {Float64Array} matrix (column-major)
*/
function toColumnMajor( n, X ) {
	var out;
	var i;
	var j;

	out = new Float64Array( n*n );
	for ( i = 0; i < n; i++ ) {
		for ( j = 0; j < n; j++ ) {
			out[ (j*n)+i ] = X[ (i*n)+j ];
		}
	}
	return out;
}

/**
* Verifies the normwise error of the Strassen–Winograd algorithm for random matrices having entries uniformly distributed on `[-1,1]`.
*
* @private
* @param {Object} t - test object
* @param {PositiveInteger} n - order
*/
function verify( t, n ) {
	var exact;
	var rand;
	var maxA;
	var maxB;
	var norm;
	var eta;
	var Bc;
	var sa;
	var sb;
	var A;
	var B;
	var C;
	var L;
	var i;

	rand = uniform.factory( -1.0, 1.0, {
		'seed': SEED+n
	});
	A = new Float64Array( n*n );
	B = new Float64Array( n*n );
	for ( i = 0; i < n*n; i++ ) {
		A[ i ] = rand();
		B[ i ] = rand();
	}
	Bc = toColumnMajor( n, B );
	maxA = maxAbs( A );
	maxB = maxAbs( B );
	norm = EPS * maxA * maxB;
	sa = scaleExponent( A );
	sb = scaleExponent( B );
	exact = exactProduct( n, A, B, sa, sb );

	// Sanity check: the conventional algorithm satisfies `η_N <= K²`...
	C = new Float64Array( n*n );
	dgemm( NT, NT, n, n, n, 1.0, A, n, 1, 0, B, n, 1, 0, 0.0, C, n, 1, 0 );
	eta = maxError( C, exact, sa+sb ) / norm;
	t.ok( eta <= n*n, '`dgemm`: η_N = ' + eta.toFixed( 3 ) + ' <= K² = ' + ( n*n ) );

	for ( L = 1; L <= 4; L++ ) {
		t.strictEqual( depth( n, n, n, CUTOFF, L ), L, 'recursion depth equals ' + L );

		// `B` row-major (blocked leaves) and column-major (naive leaves):
		C = new Float64Array( n*n );
		ncalls = 0;
		base( NT, NT, n, n, n, 1.0, A, n, 1, 0, B, n, 1, 0, 0.0, C, n, 1, 0, CUTOFF, L );
		eta = maxError( C, exact, sa+sb ) / norm;
		t.strictEqual( ncalls, 1, 'takes the recursive path' );
		t.ok( eta <= fW( n, L ), 'L = ' + L + ' (B row-major): η_N = ' + eta.toFixed( 3 ) + ' <= f_W = ' + fW( n, L ).toFixed( 1 ) + ' (ρ_N = ' + ( eta/fW( n, L ) ).toExponential( 2 ) + ')' );

		C = new Float64Array( n*n );
		ncalls = 0;
		base( NT, NT, n, n, n, 1.0, A, n, 1, 0, Bc, 1, n, 0, 0.0, C, 1, n, 0, CUTOFF, L );
		eta = maxError( toColumnMajor( n, C ), exact, sa+sb ) / norm; // transposing a square column-major matrix yields its row-major copy
		t.strictEqual( ncalls, 1, 'takes the recursive path' );
		t.ok( eta <= fW( n, L ), 'L = ' + L + ' (B and C column-major): η_N = ' + eta.toFixed( 3 ) + ' <= f_W = ' + fW( n, L ).toFixed( 1 ) + ' (ρ_N = ' + ( eta/fW( n, L ) ).toExponential( 2 ) + ')' );
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof base, 'function', 'main export is a function' );
	t.end();
});

tape( 'the normwise error satisfies the Winograd-variant bound η_N <= f_W (n = 65, L = 1, ..., 4; exact BigInt reference)', opts, function test( t ) {
	verify( t, 65 );
	t.end();
});

tape( 'the normwise error satisfies the Winograd-variant bound η_N <= f_W (n = 128, L = 1, ..., 4; exact BigInt reference)', opts, function test( t ) {
	verify( t, 128 );
	t.end();
});

tape( 'the normwise error satisfies the Winograd-variant bound η_N <= f_W (n = 257, L = 1, ..., 4; exact BigInt reference)', opts, function test( t ) {
	verify( t, 257 );
	t.end();
});

tape( 'the public ndarray interface satisfies the Winograd-variant bound η_N <= f_W (n = 2*cutoff+2; default cutoff and levels)', opts, function test( t ) {
	var exact;
	var rand;
	var eta;
	var A;
	var B;
	var C;
	var L;
	var n;
	var i;

	// Use a size which recurses twice at the default cutoff (with dynamic peeling at the second level when the cutoff is even):
	n = ( 2*defaults.CUTOFF ) + 2;
	rand = uniform.factory( -1.0, 1.0, {
		'seed': SEED
	});
	A = new Float64Array( n*n );
	B = new Float64Array( n*n );
	for ( i = 0; i < n*n; i++ ) {
		A[ i ] = rand();
		B[ i ] = rand();
	}
	L = depth( n, n, n, defaults.CUTOFF, defaults.LEVELS );
	t.strictEqual( L, min( 2, defaults.LEVELS ), 'the problem recurses (n = ' + n + ', L = ' + L + ')' );
	exact = exactProduct( n, A, B, scaleExponent( A ), scaleExponent( B ) );
	C = new Float64Array( n*n );
	ncalls = 0;
	ndarray( NT, NT, n, n, n, 1.0, A, n, 1, 0, B, n, 1, 0, 0.0, C, n, 1, 0 );
	t.strictEqual( ncalls, 1, 'takes the recursive path' );
	eta = maxError( C, exact, scaleExponent( A )+scaleExponent( B ) ) / ( EPS*maxAbs( A )*maxAbs( B ) );
	t.ok( eta <= fW( n, L ), 'η_N = ' + eta.toFixed( 3 ) + ' <= f_W = ' + fW( n, L ).toFixed( 1 ) + ' (L = ' + L + ')' );
	t.end();
});
